//! W3C XML conformance suite harness.
//!
//! Reads the manifest generated by tools/gen_xmlconf_manifest.py and checks
//! xmlz's verdict against each test's expected classification:
//!
//!   valid    -> must parse without error
//!   invalid  -> must parse (DTD validity is not checked)
//!   not-wf   -> must be rejected
//!   error    -> optional; counted but not enforced
//!
//! XML 1.1 and namespace tests are reported separately because they exercise
//! features outside the XML 1.0 core parser.

const std = @import("std");
const xmlz = @import("xmlz");

const Entry = struct {
    uri: []const u8,
    id: []const u8 = "",
    type: []const u8,
    entities: []const u8 = "",
    sections: []const u8 = "",
    namespace: bool = false,
    xml11: bool = false,
    recommendation: []const u8 = "",
    edition: []const u8 = "",
    version: []const u8 = "",
};

const Result = enum {
    parsed,
    rejected,
    skipped,
    missing,
    decode_error,
};

const Outcome = struct {
    entry: Entry,
    result: Result,
    err: ?anyerror = null,
    offset: usize = 0,
    line: usize = 0,
    column: usize = 0,
    validation_issues: usize = 0,
    validation_error: ?anyerror = null,
    validated: bool = false,
};

const ResolverContext = struct {
    io: std.Io,
    arena: *std.heap.ArenaAllocator,
    base_dir: []const u8,
};

fn resolveExternal(
    context: ?*anyopaque,
    system_id: []const u8,
    public_id: ?[]const u8,
    base_system_id: ?[]const u8,
) ?xmlz.parser.ExternalResource {
    _ = public_id;
    const ctx: *ResolverContext = @ptrCast(@alignCast(context orelse return null));
    const allocator = ctx.arena.allocator();
    var directory = ctx.base_dir;
    if (base_system_id) |base| {
        // The parser passes the resolved URI of the referencing resource.
        directory = std.fs.path.dirname(base) orelse ctx.base_dir;
    }
    const path = std.fs.path.join(allocator, &.{ directory, system_id }) catch
        return null;
    const data = std.Io.Dir.cwd().readFileAlloc(
        ctx.io,
        path,
        allocator,
        .limited(32 * 1024 * 1024),
    ) catch return null;
    return .{ .data = data, .uri = path };
}

const Stats = struct {
    total: usize = 0,
    passed: usize = 0,
    failed: usize = 0,
    skipped: usize = 0,
    optional: usize = 0,
};

pub fn main(init: std.process.Init) !void {
    const gpa = init.gpa;
    const io = init.io;

    var args = try std.process.Args.Iterator.initAllocator(init.minimal.args, gpa);
    defer args.deinit();
    _ = args.next();

    const suite_dir = args.next() orelse "testdata/xmlconf";
    var verbose = false;
    var only: ?[]const u8 = null;
    while (args.next()) |arg| {
        if (std.mem.eql(u8, arg, "--verbose") or std.mem.eql(u8, arg, "--debug")) {
            verbose = true;
        } else if (std.mem.eql(u8, arg, "--only")) {
            only = args.next();
        }
    }

    const cwd = std.Io.Dir.cwd();
    const manifest_path = try std.fs.path.join(gpa, &.{ suite_dir, "manifest.json" });
    defer gpa.free(manifest_path);
    const manifest_bytes = cwd.readFileAlloc(
        io,
        manifest_path,
        gpa,
        .limited(64 * 1024 * 1024),
    ) catch |err| {
        std.debug.print("cannot read manifest {s}: {t}\n", .{ manifest_path, err });
        return err;
    };
    defer gpa.free(manifest_bytes);

    const parsed = try std.json.parseFromSlice(
        []const Entry,
        gpa,
        manifest_bytes,
        .{ .ignore_unknown_fields = true },
    );
    defer parsed.deinit();

    var outcomes = std.ArrayList(Outcome).empty;
    defer outcomes.deinit(gpa);

    for (parsed.value) |entry| {
        if (only) |filter| {
            if (std.mem.indexOf(u8, entry.uri, filter) == null and
                std.mem.indexOf(u8, entry.id, filter) == null)
            {
                continue;
            }
        }
        const outcome = try runTest(gpa, io, suite_dir, entry, verbose);
        try outcomes.append(gpa, outcome);
    }

    try report(gpa, outcomes.items, verbose);
}

fn runTest(
    gpa: std.mem.Allocator,
    io: std.Io,
    suite_dir: []const u8,
    entry: Entry,
    debug: bool,
) !Outcome {
    // The suite marks tests that only apply to XML 1.0 editions 1-4. xmlz
    // implements the Fifth Edition name/character productions.
    if (entry.edition.len != 0 and
        std.mem.indexOfScalar(u8, entry.edition, '5') == null)
    {
        return .{ .entry = entry, .result = .skipped };
    }

    const path = try std.fs.path.join(gpa, &.{ suite_dir, entry.uri });
    defer gpa.free(path);

    const source = std.Io.Dir.cwd().readFileAlloc(
        io,
        path,
        gpa,
        .limited(32 * 1024 * 1024),
    ) catch |err| switch (err) {
        error.FileNotFound => return .{ .entry = entry, .result = .missing },
        else => return .{ .entry = entry, .result = .missing, .err = err },
    };
    defer gpa.free(source);

    const decoded = xmlz.encoding.decodeAlloc(gpa, source, 32 * 1024 * 1024) catch |err| {
        return .{ .entry = entry, .result = .decode_error, .err = err };
    };
    defer gpa.free(decoded);

    var arena = std.heap.ArenaAllocator.init(gpa);
    defer arena.deinit();
    const document_dir = std.fs.path.dirname(path) orelse ".";
    var resolver_context: ResolverContext = .{
        .io = io,
        .arena = &arena,
        .base_dir = document_dir,
    };

    var parser = xmlz.parser.Parser.init(decoded, .{
        .allocator = gpa,
        .resolver = .{
            .context = &resolver_context,
            .resolve = resolveExternal,
        },
        .namespaces = entry.namespace,
    });
    defer parser.deinit();
    while (true) {
        const event = parser.next() catch |err| {
            const offset = parser.errorOffset();
            const position = parser.lineColumn(offset);
            if (debug) {
                if (@errorReturnTrace()) |trace| std.debug.dumpErrorReturnTrace(trace);
                const error_source = parser.errorInput();
                var lines = std.mem.splitScalar(u8, error_source, '\n');
                var line_number: usize = 1;
                while (lines.next()) |line| : (line_number += 1) {
                    if (line_number == position.line) {
                        std.debug.print(
                            "DEBUG {s}: {s} at {d}:{d}: {s}\n",
                            .{ entry.uri, @errorName(err), position.line, position.column, line },
                        );
                        break;
                    }
                }
            }
            return .{
                .entry = entry,
                .result = .rejected,
                .err = err,
                .offset = offset,
                .line = position.line,
                .column = position.column,
            };
        };
        if (event == null) break;
    }

    var outcome: Outcome = .{ .entry = entry, .result = .parsed };
    const validate = std.mem.eql(u8, entry.type, "valid") or
        std.mem.eql(u8, entry.type, "invalid");
    if (validate) {
        var document = xmlz.dom.Document.parse(gpa, decoded, .{
            .parser = .{
                .resolver = .{
                    .context = &resolver_context,
                    .resolve = resolveExternal,
                },
                .namespaces = entry.namespace,
            },
            .keep_comments = true,
            .keep_pis = true,
        }) catch |err| {
            outcome.validation_error = err;
            return outcome;
        };
        defer document.deinit();
        if (document.dtd) |dtd| {
            if (dtd.doctype_name.len != 0 or
                dtd.elements.len != 0 or
                dtd.attributes.len != 0)
            {
                outcome.validated = true;
                const issues = xmlz.validation.validate(
                    gpa,
                    &document,
                    dtd,
                ) catch |err| {
                    outcome.validation_error = err;
                    return outcome;
                };
                defer gpa.free(issues);
                outcome.validation_issues = issues.len;
                if (debug) {
                    for (issues) |issue| {
                        std.debug.print(
                            "VALIDATION {s} {s}: {s} node={d} attr={s} name={s}\n",
                            .{
                                entry.type,
                                entry.uri,
                                @tagName(issue.kind),
                                issue.node,
                                issue.attribute,
                                issue.name,
                            },
                        );
                    }
                }
            }
        }
    }
    return outcome;
}

fn report(gpa: std.mem.Allocator, outcomes: []const Outcome, verbose: bool) !void {
    var stats: Stats = .{};
    var failures: [512]Outcome = undefined;
    var failure_count: usize = 0;
    var missing: [64]Outcome = undefined;
    var missing_count: usize = 0;
    var decode_failures: [64]Outcome = undefined;
    var decode_failure_count: usize = 0;
    var optional: [32]Outcome = undefined;
    var optional_count: usize = 0;

    var by_entities = std.StringHashMap(Stats).init(gpa);
    defer by_entities.deinit();
    var by_error = std.StringHashMap(Stats).init(gpa);
    defer by_error.deinit();

    for (outcomes) |outcome| {
        stats.total += 1;
        if (outcome.result == .skipped) {
            stats.skipped += 1;
            continue;
        }
        const expected = outcome.entry.type;
        const should_parse = std.mem.eql(u8, expected, "valid") or
            std.mem.eql(u8, expected, "invalid");
        const should_reject = std.mem.eql(u8, expected, "not-wf");
        const optional_test = std.mem.eql(u8, expected, "error");

        const passed = switch (outcome.result) {
            .parsed => blk: {
                if (!should_parse) break :blk false;
                if (outcome.validation_error != null) break :blk false;
                if (std.mem.eql(u8, expected, "valid")) {
                    break :blk !outcome.validated or
                        outcome.validation_issues == 0;
                }
                if (std.mem.eql(u8, expected, "invalid")) {
                    break :blk !outcome.validated or
                        outcome.validation_issues > 0;
                }
                break :blk true;
            },
            .rejected, .decode_error => should_reject,
            .missing, .skipped => false,
        };

        if (optional_test) {
            stats.optional += 1;
            if (optional_count < optional.len) {
                optional[optional_count] = outcome;
                optional_count += 1;
            }
            continue;
        }

        if (outcome.result == .missing) {
            stats.failed += 1;
            if (missing_count < missing.len) {
                missing[missing_count] = outcome;
                missing_count += 1;
            }
            continue;
        }
        if (outcome.result == .decode_error and should_parse) {
            stats.failed += 1;
            if (decode_failure_count < decode_failures.len) {
                decode_failures[decode_failure_count] = outcome;
                decode_failure_count += 1;
            }
            continue;
        }

        const entities_key = if (outcome.entry.entities.len == 0)
            "unspecified"
        else
            outcome.entry.entities;
        const bucket = try by_entities.getOrPut(entities_key);
        if (!bucket.found_existing) bucket.value_ptr.* = .{};
        bucket.value_ptr.total += 1;

        if (passed) {
            stats.passed += 1;
            bucket.value_ptr.passed += 1;
        } else {
            stats.failed += 1;
            bucket.value_ptr.failed += 1;
            const error_key = if (outcome.validation_error) |err|
                @errorName(err)
            else if (outcome.err) |err|
                @errorName(err)
            else if (std.mem.eql(u8, expected, "invalid"))
                "missing-validation-issue"
            else
                "unexpected-validation-issue";
            const error_bucket = try by_error.getOrPut(error_key);
            if (!error_bucket.found_existing) error_bucket.value_ptr.* = .{};
            error_bucket.value_ptr.total += 1;
            if (failure_count < failures.len) {
                failures[failure_count] = outcome;
                failure_count += 1;
            }
        }
    }

    std.debug.print(
        "\nW3C XML conformance: {d} total, {d} passed, {d} failed, {d} skipped (edition 1-4 only), {d} optional\n",
        .{ stats.total, stats.passed, stats.failed, stats.skipped, stats.optional },
    );

    var it = by_entities.iterator();
    while (it.next()) |bucket| {
        std.debug.print(
            "  entities={s}: {d}/{d} passed ({d} failed)\n",
            .{
                bucket.key_ptr.*,
                bucket.value_ptr.passed,
                bucket.value_ptr.total,
                bucket.value_ptr.failed,
            },
        );
    }

    var error_it = by_error.iterator();
    while (error_it.next()) |bucket| {
        std.debug.print("  error {s}: {d}\n", .{ bucket.key_ptr.*, bucket.value_ptr.total });
    }

    if (failure_count != 0) {
        std.debug.print("\nFirst failures:\n", .{});
        for (failures[0..failure_count]) |outcome| {
            const err_name = if (outcome.err) |err| @errorName(err) else "parsed";
            std.debug.print(
                "  [{s}] {s} ({s}): {s} at {d}:{d} offset {d}\n",
                .{
                    outcome.entry.type,
                    outcome.entry.id,
                    outcome.entry.uri,
                    err_name,
                    outcome.line,
                    outcome.column,
                    outcome.offset,
                },
            );
        }
    }
    if (missing_count != 0) {
        std.debug.print("\nMissing files:\n", .{});
        for (missing[0..missing_count]) |outcome| {
            std.debug.print("  {s}\n", .{outcome.entry.uri});
        }
    }
    if (decode_failure_count != 0) {
        std.debug.print("\nDecode failures:\n", .{});
        for (decode_failures[0..decode_failure_count]) |outcome| {
            const err_name = if (outcome.err) |err| @errorName(err) else "?";
            std.debug.print("  {s}: {s}\n", .{ outcome.entry.uri, err_name });
        }
    }
    if (verbose and optional_count != 0) {
        std.debug.print("\nOptional tests:\n", .{});
        for (optional[0..optional_count]) |outcome| {
            const err_name = if (outcome.err) |err| @errorName(err) else "parsed";
            std.debug.print(
                "  {s}: {s}\n",
                .{ outcome.entry.uri, err_name },
            );
        }
    }

    if (stats.failed != 0) return error.ConformanceFailures;
}
